$ErrorActionPreference='Stop';$root=$PSScriptRoot
Import-Module (Join-Path $root 'src/VerticalSlice.psm1') -Force -DisableNameChecking
Import-Module (Join-Path $root 'src/Notebook.psm1') -Force -DisableNameChecking
function Assert($Condition,[string]$Message){if(-not$Condition){throw "FAILED: $Message"}}
function Intent([string]$Actor,[string]$Action,[string]$Target,[string]$Method=$null,[string]$Spell=$null){[pscustomobject]@{Actor=$Actor;Action=$Action;Target=$Target;Method=$Method;Area=$null;CommunicativeIntent=$null;Spell=$Spell;RawInput='test'}}
$session=New-CallumStudySession $root;$public=Get-SlicePlayerState $session
Assert ($session.State.Player.Location-eq'callum_study'-and$public.location.id-eq'callum_study') '1 new study session initializes'
$json=$public|ConvertTo-Json -Depth 15;Assert ($json-notmatch'bloodstain|scorch_marks|rope_fibers|wall_safe|burned_note|hidden_truth|forcibly removed') '2 hidden clues absent from player response'
foreach($name in @('writing desk','fireplace','rug and floor','large painting','bookshelves','window','study door')){Assert ($public.visible_objects-contains$name) "3 visible object: $name"}
$blood=Resolve-SliceIntent $session (Intent Armand examine rug) 6;Assert ($session.State.Notebook.Clues.Contains('bloodstain')-and$session.State.Notebook.Clues.bloodstain.known_facts[0]-match'dried blood') '4 blood focused passive tier discovers'
Assert ($session.State.Notebook.Clues.bloodstain.known_facts-notmatch'too little|moved from') '5 blood higher tiers hidden'
$count=$session.State.Notebook.Clues.bloodstain.known_facts.Count;Resolve-SliceIntent $session (Intent Armand examine rug) 1|Out-Null;Assert ($session.State.Notebook.Clues.bloodstain.known_facts.Count-eq$count) '6 failed interpretation reveals no extra fact'
$scorch=Resolve-SliceIntent $session (Intent Armand investigate fireplace) 17;Assert ($session.State.Notebook.Clues.scorch_marks.known_facts-match'magical or occult energy') '7 scorch supports active Occult interpretation'
$detectSession=New-CallumStudySession $root;$detect=Resolve-SliceIntent $detectSession (Intent Armand cast fireplace $null detect_magic);$detectJson=$detect|ConvertTo-Json -Depth 10;Assert ($detectSession.State.Notebook.Clues.Contains('occult_residue')-and$detectJson-notmatch'who cast|cultist|identity of the caster') '8 Detect Magic establishes presence, not explanation'
$rope=Resolve-SliceIntent $session (Intent Armand examine writing_desk) 11;Assert ($session.State.Notebook.Clues.Contains('rope_fibers')) '9 rope fibers discovered'
Assert (-not(Get-SlicePlayerState $session).slice_state.safe_discovered) '10 safe hidden initially'
$routeA=New-CallumStudySession $root;Resolve-SliceIntent $routeA (Intent Armand examine large_painting)|Out-Null;$routeB=New-CallumStudySession $root;$g=Resolve-SliceIntent $routeB (Intent Guillermo examine large_painting) 12;Assert ($routeA.SafeDiscovered-and$routeB.SafeDiscovered) '11 safe discovered through painting or Guillermo'
$stateAfter=Get-SlicePlayerState $routeA;Assert ($stateAfter.visible_objects-contains'concealed safe') '12 safe state persists after discovery'
$openA=Resolve-SliceIntent $routeA (Intent Armand open wall_safe 'work the lock with Finesse') 12;$openBSession=New-CallumStudySession $root;Resolve-SliceIntent $openBSession (Intent Armand examine paneled_wall)|Out-Null;$openB=Resolve-SliceIntent $openBSession (Intent Armand use wall_safe crowbar) 7;Assert ($routeA.SafeOpen-and$openBSession.SafeOpen-and$openB.Degree-eq'Setback') '13 safe opens through explicit finesse or crowbar setback'
Assert (-not$routeA.State.Player.Inventory.Contains('burned_note')-and-not$routeA.LeadRecovered) '14 lead unavailable before recovery'
$lead=Resolve-SliceIntent $routeA (Intent Armand take burned_note);Assert ($routeA.LeadRecovered-and$routeA.State.Player.Inventory.Contains('burned_note')-and$routeA.State.Notebook.Clues.Contains('external_lead')-and(Get-SlicePlayerState $routeA).slice_state.ending_reached) '15 lead triggers ending and enters Notebook'
Assert ($g.Degree-in@('Success','Exceptional Success')-and$g.Events-match'Guillermo') '16 Guillermo can inspect target'
$gFailSession=New-CallumStudySession $root;$gFail=Resolve-SliceIntent $gFailSession (Intent Guillermo examine large_painting) 1;Assert (-not$gFailSession.SafeDiscovered-and$gFail.Degree-notin@('Success','Exceptional Success')) '17 Guillermo result is engine authoritative'
$hintSession=New-CallumStudySession $root;Resolve-SliceIntent $hintSession (Intent Armand examine rug) 11|Out-Null;$hint=Resolve-SliceIntent $hintSession (Intent Armand examine writing_desk) 11;Assert ($hintSession.HintDelivered-and$hint.Events-match'looks at the large painting') '18 hint target selected by engine'
Assert (($hint.Events-join' ')-notmatch'safe behind|solution|open the') '19 hint behavior does not state solution'
Assert ($session.State.Notebook.Clues.Count-ge3) '20 Notebook clue updates occur'
$theory=New-NotebookTheory $session.State removal 'Forced removal' 'Callum may have been taken from the room.';Assert ($theory.classification-eq'player_belief') '21 theory remains belief'
Add-NotebookTheoryLink $session.State removal clue bloodstain;$relevance=Get-NotebookRelevance $session.State callum_study bloodstain @('rope_fibers') @() 4;Assert (@($relevance.id)-contains'bloodstain'-and@($relevance.id)-contains'removal') '22 relevance surfaces linked evidence'
$packetJson=$blood.Handoff|ConvertTo-Json -Depth 12;Assert ($packetJson-notmatch'too little blood|injured person was moved|hidden_truth') '23 hidden tiers absent from narrator handoff'
$move=Resolve-SliceIntent $session (Intent Armand move study_door);Assert ($session.State.Player.Location-eq'landing'-and$session.State.Notebook.Clues.Contains('bloodstain')) '24 leaving preserves state'
$return=Resolve-SliceIntent $session (Intent Armand move study_entrance);Assert ($session.State.Player.Location-eq'callum_study'-and$return.Events-match'returns to the changed study') '25 return uses changed-state context'
Resolve-SliceIntent $routeA (Intent Armand move study_door)|Out-Null;Resolve-SliceIntent $routeA (Intent Armand move study_entrance)|Out-Null;Assert ($routeA.SafeOpen-and$routeA.LeadRecovered) '26 safe contents remain changed after return'
$failSession=New-CallumStudySession $root;Resolve-SliceIntent $failSession (Intent Armand examine large_painting)|Out-Null;$beforeTime=$failSession.State.Time.ElapsedMinutes;$failedOpen=Resolve-SliceIntent $failSession (Intent Armand open wall_safe 'work the lock with Finesse') 1;Assert ($failedOpen.Degree-eq'Failure'-and$failSession.State.Time.ElapsedMinutes-gt$beforeTime) '27 failure advances situation/time'
Assert ($openB.Degree-eq'Setback'-and$openB.Events-match'bends|echoes|shrieks') '28 setback gives progress plus consequence'
$badThenGood={param($prompt,$attempt)if($attempt-eq0){[pscustomobject]@{Text=('I decide '+('word '*150))}}else{[pscustomobject]@{Text='inspect the mark. The dark discoloration remains visible.'}}};$retry=Invoke-SliceNarration $session $blood $badThenGood 2 $root;Assert ($retry.RetryOccurred-and-not$retry.FallbackUsed-and$retry.Validation.Passed) '29a validation rejection triggers safe retry'
$alwaysBad={param($prompt,$attempt)[pscustomobject]@{Text='I decide to invent an action.'}};$fallback=Invoke-SliceNarration $session $blood $alwaysBad 2 $root;Assert ($fallback.FallbackUsed-and$fallback.Text-match'dark mark|discoloration'-and$fallback.Text-notmatch'I decide') '29b repeated rejection triggers fact fallback'
$groundingBase=[pscustomobject]@{Passed=$true;Lexical=$null;Structural=$null};$closed=New-CallumStudySession $root;$fake=Test-SliceNarrationGrounding $closed $blood 'You see the safe standing open with its contents visible.' $groundingBase;Assert (-not$fake.Passed-and$fake.GroundingErrors.Count) '29c slice grounding rejects authoritative-state contradiction'
$routeA.SafeOpen=$false;$picked=Test-SliceNarrationGrounding $routeA $blood "You see the safe's lock has been picked." $groundingBase;Assert (-not$picked.Passed) '29d slice grounding rejects invented picked lock'
$continuity=Test-SliceNarrationGrounding $routeA $blood 'You see the safe; it was not there before.' $groundingBase;Assert (-not$continuity.Passed) '29e slice grounding rejects false continuity'
$epistemic=Test-SliceNarrationGrounding $routeA $blood 'You do not know what Guillermo means.' $groundingBase;Assert (-not$epistemic.Passed) '29f slice grounding rejects player epistemic assignment'
$publicJson=Get-SlicePlayerState $session|ConvertTo-Json -Depth 15;Assert ($publicJson-notmatch'hidden_truth|CaseTruth|Skills|Nerve|DC|HighestTier|wall_safe') '30 Godot response excludes secret fields'
$clean=New-CallumStudySession $root;Assert (-not$clean.SafeDiscovered-and-not$clean.LeadRecovered-and$clean.State.Notebook.Clues.Count-eq0) '31 restart creates clean session'
Write-Host 'Vertical slice backend tests passed: 31 required gameplay and safety scenarios.'
